<?php

namespace Copyleaks;

use Copyleaks\CopyleaksAiImageDetectionRequestModel;

/**
 * AI Image Detection. Calls throw the exceptions listed on the Copyleaks class.
 */
class AiImagedetectionClient{

    /**
     * Check whether an image was fully or partly generated by AI.
     * https://docs.copyleaks.com/reference/actions/ai-image-detector/check
     * @param CopyleaksAuthToken $authToken
     * @param string $scanId Your own scan ID.
     * @param CopyleaksAiImageDetectionRequestModel $submission
     * @return mixed Decoded JSON, see CopyleaksAiImageDetectionResponseModel::fromArray().
     */
    public function submit(CopyleaksAuthToken $authToken, string $scanId, CopyleaksAiImageDetectionRequestModel $submission)
    {
        return CopyleaksClientUtils::sendScanRequest($authToken, 'POST-JSON', '/v1/ai-image-detector/{scanId}/check', $scanId, $submission);
    }

    /**
     * Submit an image URL for AI detection. Answers 201 right away; the result is sent to
     * $submission->webhooks->url, read it with CopyleaksAiImageDetectionResponseModel::fromArray().
     * https://docs.copyleaks.com/reference/actions/ai-image-detector/submit
     * @param CopyleaksAuthToken $authToken
     * @param string $scanId Your own scan ID.
     * @param CopyleaksAiImageDetectionAsyncRequestModel $submission
     * @return mixed Decoded JSON (an empty object).
     */
    public function submitAsync(CopyleaksAuthToken $authToken, string $scanId, CopyleaksAiImageDetectionAsyncRequestModel $submission)
    {
        return CopyleaksClientUtils::sendScanRequest($authToken, 'PUT', '/v1/ai-image-detector-async/{scanId}/submit', $scanId, $submission);
    }
}
